using System.IO;
using System.Text.Json;
using SharpWR.Sim.Numerics;

namespace SharpWR.Sim.Tests
{
    /// <summary>Loads fixtures generated by tools/parity/*.py (copied next to the test assembly).</summary>
    internal static class Fixtures
    {
        public static JsonElement Load(string fileName)
        {
            string path = Path.Combine(TestContextDir(), "fixtures", fileName);
            using FileStream stream = File.OpenRead(path);
            return JsonDocument.Parse(stream).RootElement.Clone();
        }

        /// <summary>Numbers are parsed from their JSON text (Python repr), never via double.</summary>
        public static Fix64 Fix(JsonElement e) => Fix64.Parse(e.GetRawText());

        public static double Double(JsonElement e) => e.GetDouble();

        // Fixtures are copied next to the test assembly (see the .csproj None items).
        private static string TestContextDir() => System.AppContext.BaseDirectory;
    }
}
